code.ADEToken.airdrop():
function airdrop() public {
 require(airAmount > 0);
 if (airLimitCount > 0 && airCountOf[msg.sender] >= airLimitCount) {
 revert();
 }
 _transfer(airSender, msg.sender, airAmount);
 airCountOf[msg.sender] = airCountOf[msg.sender].add(1);
 Airdrop(msg.sender, airCountOf[msg.sender], airAmount);
 }

code.BurnToken.burn(uint256):
function burn(uint256 _value) public returns (bool success) {
 require(balanceOf[msg.sender] >= _value);
 balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
 totalSupply = totalSupply.sub(_value);
 Burn(msg.sender, _value);
 return true;
 }

code.BurnToken.burnFrom(address,uint256):
function burnFrom(address _from, uint256 _value) public returns (bool success) {
 require(balanceOf[_from] >= _value);
 require(_value <= allowance[_from][msg.sender]);
 balanceOf[_from] = balanceOf[_from].sub(_value);
 allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
 totalSupply = totalSupply.sub(_value);
 Burn(_from, _value);
 return true;
 }

code.LockToken..transfer(address,address,uint:
function _transfer(address _from, address _to, uint _value) internal {
 require(balanceOf[_from] >= _value);
 uint256 remain = balanceOf[_from].sub(_value);
 uint256 length = lockedAddresses[_from].length;
 for (uint256 i = 0; i < length; i++) {
 LockMeta storage meta = lockedAddresses[_from][i];
 if(block.timestamp < meta.endtime && remain < meta.remain){
 revert();
 }
 }
 super._transfer(_from, _to, _value);
 }

code.BaseToken..transfer(address,address,uint:
function _transfer(address _from, address _to, uint _value) internal {
 require(_to != address(0));
 require(balanceOf[_from] >= _value);
 balanceOf[_from] = balanceOf[_from].sub(_value);
 balanceOf[_to] = balanceOf[_to].add(_value);
 Transfer(_from, _to, _value);
 }

code.BaseToken.transfer(address,uint256):
function transfer(address _to, uint256 _value) public returns (bool success) {
